// Foundry VTT v12 — Effect-safe toggle for system.props.isWeak
(async () => {
  const PATH = "system.props.isWeak";
  const effectActor = (typeof actor !== "undefined" && actor) ? actor : canvas.tokens.controlled[0]?.actor;
  if (!effectActor) return;
  const current = foundry.utils.getProperty(effectActor, PATH) ?? false;
  await effectActor.update({ [PATH]: !current });
})();

