onCreate.script:
// Foundry VTT v12 — Effect-safe toggle for system.props.isSlow
// Works best when run by the Effect Macro module (uses the effect owner `actor`).
// Falls back to the first selected token's actor only if no effect context is present.

(async () => {
  const PATH = "system.props.isSlow";

  // Prefer the effect owner `actor` (provided by Effect Macro when the macro fires).
  // Fallback to selected token's actor if you ever run this by hand.
  const effectActor = (typeof actor !== "undefined" && actor) ? actor : canvas.tokens.controlled[0]?.actor;
  if (!effectActor) {
    ui.notifications?.warn("[isSlow Toggle] No actor context (need effect owner or a selected token).");
    return;
  }

  // Read current value (default to false when missing), then toggle.
  const current = foundry.utils.getProperty(effectActor, PATH) ?? false;
  const next = !current;

  await effectActor.update({ [PATH]: next });
})();

